UPDATE tools SET long_description = E'Datadog, c''est observabilité complète : logs, métriques, APM, alertes en temps réel. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les cto-lead-tech et les developpeur-solo.\n\nGain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : infrastructure cloud complexe avec besoin d''alerting. À éviter si : stack simple — Sentry gratuit suffit pour les erreurs. Pertinent à partir de 3+ services en production. Alternative gratuite à considérer : sentry.', long_description_en = E'Datadog is full observability: logs, metrics, APM, real-time alerts. Core features are free, with paid plans for advanced use. Most relevant for cto-lead-tech and solo developers.\n\nEstimated time saving: 5h/month with regular use.\n\nFree alternative worth considering: sentry.' WHERE slug = 'datadog';
